mapper.update:
UPDATE class_record
SET rating = #{rating}
WHERE record_id = #{recordId}

UPDATE class_record
SET completed_sessions = #{completed},
    status = #{status}
WHERE record_id = #{recordId}

mapper.select:
SELECT count(*) FROM class_record
WHERE class_id = #{classId}
  AND status <> 2

SELECT member_id AS memberId, member_name AS memberName, gender, class_id AS classId, class_name AS className, record_id AS recordId, join_time AS joinTime, status, rating FROM v_member_course_rating
AND rating >= #{minRating}
AND gender = #{gender}
ORDER BY rating DESC, join_time DESC, record_id DESC LIMIT #{limit}
